int myAtoi(char *str) {
  char *s;
  long n = 0;
  int sign = 0;

  while (*str == ' ' || *str == '\t') {
    str++;
  }

  if (*str == '-') {
    if (isdigit(*++str)) {
      sign = 1;
    } else {
      return 0;
    }
  }

  if (*str == '+') {
    if (isdigit(*++str)) {
      sign = 0;
    } else {
      return 0;
    }
  }

  for (s = str; *s != '\0'; s++) {
    if (isdigit(*s)) {
      int d = *s - '0';
      if (sign) {
        if (-n < (INT_MIN + d) / 10) {
          n = INT_MIN;
          break;
        }
      } else {
        if (n > (INT_MAX - d) / 10) {
          n = INT_MAX;
          break;
        }
      }
      n = n * 10 + d;
    } else {
      break;
    }
  }

  return sign ? -n : n;
}

class Solution {
public:
  int myAtoi(string str) {
    int i = 0, n = str.size();
    while (i < n && str[i] == ' ') i++;

    int sign = 1;
    if (i < n && (str[i] == '+' || str[i] == '-')) {
      sign = str[i] == '-' ? -1 : 1;
      i++;
    }

    long long num = 0;
    while (i < n && isdigit(str[i])) {
      num = num * 10 + (str[i] - '0');
      if (sign == 1 && num > INT_MAX) return INT_MAX;
      if (sign == -1 && -num < INT_MIN) return INT_MIN;
      i++;
    }

    return (int)(sign * num);
  }
};

