class Solution {
  public int myAtoi(String str) {
    int i = 0, n = str.length();
    while (i < n && str.charAt(i) == ' ') {
      i++;
    }

    int sign = 1;
    if (i < n && (str.charAt(i) == '+' || str.charAt(i) == '-')) {
      sign = str.charAt(i) == '-' ? -1 : 1;
      i++;
    }

    long num = 0;
    while (i < n && Character.isDigit(str.charAt(i))) {
      num = num * 10 + (str.charAt(i) - '0');
      if (sign == 1 && num > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
      }
      if (sign == -1 && -num < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
      }
      i++;
    }

    return (int) (sign * num);
  }
}

class Solution:
    def myAtoi(self, s: str) -> int:
        i, n = 0, len(s)
        while i < n and s[i] == " ":
            i += 1

        sign = 1
        if i < n and s[i] in "+-":
            if s[i] == "-":
                sign = -1
            i += 1

        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1

        num *= sign
        if num < -2 ** 31:
            return -2 ** 31
        if num > 2 ** 31 - 1:
            return 2 ** 31 - 1
        return num

impl Solution {
  pub fn my_atoi(s: String) -> i32 {
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut i = 0;
    while i < n && bytes[i] == b' ' {
      i += 1;
    }

    let mut sign = 1i64;
    if i < n && (bytes[i] == b'+' || bytes[i] == b'-') {
      if bytes[i] == b'-' {
        sign = -1;
      }
      i += 1;
    }

    let mut num = 0i64;
    while i < n && bytes[i].is_ascii_digit() {
      num = num * 10 + (bytes[i] - b'0') as i64;
      if sign == 1 && num > i32::MAX as i64 {
        return i32::MAX;
      }
      if sign == -1 && -num < i32::MIN as i64 {
        return i32::MIN;
      }
      i += 1;
    }

    (sign * num) as i32
  }
}

const myAtoi = (s: string): number => {
  const MAX = 2 ** 31 - 1;
  const MIN = -(2 ** 31);

  let i = 0;
  const n = s.length;
  while (i < n && s[i] === ' ') i++;

  let sign = 1;
  if (i < n && (s[i] === '+' || s[i] === '-')) {
    if (s[i] === '-') sign = -1;
    i++;
  }

  let num = 0;
  while (i < n && s[i] >= '0' && s[i] <= '9') {
    num = num * 10 + Number(s[i]);
    if (sign === 1 && num > MAX) return MAX;
    if (sign === -1 && -num < MIN) return MIN;
    i++;
  }

  return sign * num;
};
